(()=>{'use strict';
const $=id=>document.getElementById(id),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('nl-NL',{maximumFractionDigits:2}).format(n||0),euro=n=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'}).format((n||0)/100),today=()=>LAAgenda.iso(new Date()),btn=(s,a,x='')=>`<button type="button" class="btn ${x}" data-team="${a}">${s}</button>`,field=(label,id,type='text',value='',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${e(value)}" ${extra}></div>`,select=(label,id,options,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('')}</select></div>`;
const state={base:localStorage.getItem('la-team-api')||(location.hostname.endsWith('.workers.dev')?location.origin:''),token:sessionStorage.getItem('la-team-token')||'',me:null,data:null,year:Number(today().slice(0,4)),page:'overzicht',dashMonth:Number(today().slice(5,7)),dashMore:false,navMore:false,recordProject:'',recordMonth:0,anchor:today(),mode:'werkweek',member:'',project:'',kind:'',selected:'',login:'login',busy:false,claimProject:'',generation:0};
const manager=()=>['owner','admin'].includes(state.me?.role),owner=()=>state.me?.role==='owner',val=id=>$(id)?.value??'',checked=id=>!!$(id)?.checked,num=id=>Number(val(id)),cents=id=>Math.round(num(id)*100),minutes=id=>Math.round(num(id)*60);
function notice(s,error=false){$('notice').textContent=s;$('notice').className='notice '+(error?'error':'ok');$('notice').hidden=false;}
function clear(){ $('notice').hidden=true; }
function endpoint(s){const u=new URL(s);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||u.pathname!=='/'||!u.hostname.endsWith('.workers.dev'))throw Error('Gebruik het HTTPS-adres van de team-Worker.');return u.origin;}
async function api(path,method='GET',data){const headers={};if(state.token)headers.Authorization='Bearer '+state.token;if(data instanceof ArrayBuffer)headers['Content-Type']='application/octet-stream';else if(data!==undefined)headers['Content-Type']='application/json';let r;try{r=await fetch(state.base+path,{method,headers,body:data instanceof ArrayBuffer?data:data!==undefined?JSON.stringify(data):undefined,cache:'no-store',redirect:'error'});}catch{throw Error('Verbinding met de server lukt niet. Probeer opnieuw.');}let j;try{j=await r.json();}catch{throw Error('Server gaf geen geldig antwoord (HTTP '+r.status+').');}if(!r.ok){if(r.status===401&&state.me)reset();throw Error(j.error||'Verzoek mislukt');}return j;}
function reset(){state.generation++;state.token='';state.me=null;state.data=null;state.member='';state.project='';state.kind='';state.selected='';state.claimProject='';state.page='overzicht';state.recordProject='';state.recordMonth=0;state.dashMore=false;state.navMore=false;state.dashMonth=state.year===Number(today().slice(0,4))?Number(today().slice(5,7)):0;sessionStorage.removeItem('la-team-token');if($('modal').open)$('modal').close();render();}
async function load(){const gen=++state.generation,year=state.year;const me=await api('/me'),data=await api('/data?year='+year);if(gen!==state.generation)return;state.me=me;state.data=data;if(!state.member)state.member=me.id;render();}
async function task(fn){if(state.busy)return;state.busy=true;clear();try{await fn();}catch(err){notice(err.message||String(err),true);if($('modal').open){const errbox=$('modal').querySelector('.team-error');if(errbox)errbox.textContent=err.message;}}finally{state.busy=false;}}
function login(){const setup=state.login==='setup',join=state.login==='join';$('app').innerHTML=`<section class="card team-login"><h1>${setup?'Bedrijf aanmaken':join?'Uitnodiging accepteren':'Inloggen'}</h1><form id="loginForm">${field('Adres team-koppeling','base','url',state.base,'required placeholder="https://…workers.dev"')}${join?field('Uitnodigingscode','invite','text','','required'):field('Bedrijfscode','slug','text','','required')}${setup?field('Bedrijfsnaam','company','text','','required')+select('Modus','mode',[['solo','Zelfstandige'],['team','Bedrijf']],'solo')+field('Installatiecode','setupKey','password','','required'):''}${setup||join?field('Naam','name','text','','required'):''}${!join?field('E-mailadres','email','email','','required'):''}${field('Wachtwoord','password','password','','required autocomplete="current-password" minlength="12"')}<button class="btn primary login-submit" type="submit">${setup?'Aanmaken':join?'Account activeren':'Inloggen'}</button></form><div class="team-actions" style="margin-top:16px">${state.login!=='login'?btn('Terug','login-mode'):btn('Uitnodiging accepteren','join-mode')+btn('Bedrijf aanmaken','setup-mode')}</div></section>`;}
const feature=k=>!!state.data?.modules?.[k],pref=k=>!!state.data?.preferences?.[k];
const pages=()=>[['overzicht','Overzicht'],['agenda','Agenda'],['registraties','Registraties'],['projecten','Projecten'],...(manager()?[['declaraties','Declaraties']]:[]),['kilometers','Kilometers'],...(manager()&&feature('clients')?[['klanten','Klanten']]:[]),...(owner()?[['medewerkers','Medewerkers']]:[]),['instellingen','Instellingen']];
const navIcons={overzicht:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',agenda:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',registraties:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',projecten:'<path d="M3 5h6l2 3h10v12H3z"/>',declaraties:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 8h6m-6 4h6m-6 4h4"/>',kilometers:'<path d="m4 16 3-8h10l3 8v4h-3v-2H7v2H4zM5 14h14M7 16h1m8 0h1"/>',medewerkers:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2a7 7 0 0 1 14 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 4 5v1"/>',instellingen:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',meer:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const navIcon=k=>'<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(navIcons[k]||navIcons.meer)+'</svg>';
function render(){
 const me=state.me;$('brand').textContent=me?.company||'Urenregistratie';$('identity').textContent=me?.name||'Ontwikkelversie';$('logo').textContent='U';
 if(me?.logo){let im=document.createElement('img');im.className='team-logo';im.src=me.logo;im.alt='Bedrijfslogo';$('logo').replaceChildren(im);}
 $('status').textContent=me?'Ingelogd · Uitloggen':'Niet ingelogd';$('year').hidden=!me;$('nav').hidden=!me;
 document.body.classList.toggle('team-signed-in',!!me);document.body.classList.toggle('team-dark',!!me&&pref('dark'));
 if(!me){login();return;}
 $('year').innerHTML=Array.from({length:11},(_,i)=>2024+i).map(y=>'<option '+(y===state.year?'selected':'')+'>'+y+'</option>').join('');
 const pp=pages();if(!pp.some(p=>p[0]===state.page))state.page='overzicht';
 const main=pp.filter(([k])=>!['kilometers','klanten','medewerkers','instellingen'].includes(k)),extra=pp.filter(([k])=>!main.some(([m])=>m===k));
 const moreOpen=state.navMore||extra.some(([k])=>k===state.page);
 const navButton=([k,label])=>'<button type="button" class="tab '+(state.page===k?'active':'')+'" data-team="page" data-page="'+k+'" '+(state.page===k?'aria-current="page"':'')+'>'+navIcon(k)+'<span>'+label+'</span></button>';
 $('nav').innerHTML=main.map(navButton).join('')+'<button type="button" class="tab team-nav-more" data-team="nav-more" aria-expanded="'+moreOpen+'">'+navIcon('meer')+'<span>Meer</span><span class="team-nav-chevron">'+(moreOpen?'−':'+')+'</span></button><div class="team-nav-secondary" '+(moreOpen?'':'hidden')+'>'+extra.map(navButton).join('')+'</div>';
 ({agenda,registraties:records,projecten:projects,overzicht:overview,declaraties:claims,medewerkers:members,instellingen:settings,kilometers:mileage,klanten:clientsPage}[state.page])();
}
const memberList=()=>[[state.me.id,'Mijn uren'],...(manager()?[['all','Alle medewerkers'],...state.data.members.filter(m=>m.id!==state.me.id).map(m=>[m.id,m.name])]:[])];
const visible=()=>state.data.entries.filter(r=>state.member==='all'||r.member_id===state.member);
const projectName=c=>state.data.projects.find(p=>p.code===c)?.name||c;
const memberName=r=>r.member_name||state.me.name;
const entries=()=>visible().map(r=>({Id:r.id,Datum:r.date,Projectnummer:r.project,Activiteit:state.member==='all'?r.activity+' · '+memberName(r):r.activity,Omschrijving:r.note,Uren:r.minutes/60,Begintijd:r.start,Eindtijd:r.end,Km:r.km,SoortUren:r.kind}));
const memberPicker=()=>state.me.mode==='team'&&manager()?`<label>Medewerker <select id="memberFilter">${memberList().map(([v,t])=>`<option value="${e(v)}" ${state.member===v?'selected':''}>${e(t)}</option>`).join('')}</select></label>`:'';
function agenda(){$('app').innerHTML=`<div class="team-toolbar">${memberPicker()}</div>${stopwatchPanel()}`+LAAgenda.render({year:state.year,anchor:state.anchor,mode:state.mode,project:state.project,kind:state.kind,selectedId:state.selected,today:today(),entries:entries(),projects:state.data.projects.map(p=>({Projectnummer:p.code,Omschrijving:p.name})),getProjectName:projectName});}
function recordTable(rows){return `<div class="card table-scroll"><table class="data-table team-table"><thead><tr><th>Datum</th><th>Medewerker</th><th>Project</th><th>Activiteit</th><th class="num">Uren</th><th class="num">Km</th><th></th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${e(r.date)}<br><small>${e(r.start&&r.end?r.start+'–'+r.end:'')}</small></td><td>${e(memberName(r))}</td><td>${e(r.project)} · ${e(projectName(r.project))}</td><td>${e(r.activity)}<br><small>${e(r.note)}</small></td><td class="num">${fmt(r.minutes/60)}</td><td class="num">${fmt(r.km)}</td><td><button class="btn small" data-team="edit-entry" data-id="${e(r.id)}">Wijzig</button>${repeatButton(r)}</td></tr>`).join('')||'<tr><td colspan="7">Geen registraties</td></tr>'}</tbody></table></div>`;}
const monthName=(i,short=false)=>new Intl.DateTimeFormat('nl-NL',{month:short?'short':'long'}).format(new Date(2026,i-1,1));
const monthOptions=()=>[[0,'Hele jaar'],...Array.from({length:12},(_,i)=>[i+1,monthName(i+1)])];
const matchMonth=(row,m)=>!m||Number(row.date.slice(5,7))===m;
const minutesOf=rows=>rows.reduce((sum,r)=>sum+Number(r.minutes||0),0);
const kmOf=rows=>rows.reduce((sum,r)=>sum+Number(r.km||0),0);
const openOf=rows=>rows.reduce((sum,r)=>sum+Math.max(0,Number(r.minutes||0)-Number(r.billed||0)),0);
const recordsFor=()=>visible().filter(r=>(!state.recordProject||r.project===state.recordProject)&&matchMonth(r,state.recordMonth));
function recordFilters(){return '<div class="team-filterbar">'+memberPicker()+select('Periode','recordMonth',monthOptions(),state.recordMonth)+select('Project','recordProject',[['','Alle projecten'],...state.data.projects.map(p=>[p.code,p.code+' · '+p.name])],state.recordProject)+'</div>';}
function records(){$('app').innerHTML='<div class="page-top"><h1>Registraties</h1>'+btn('+ Registratie','new-entry','primary')+'</div>'+recordFilters()+recordTable(recordsFor());}
function mileage(){const rows=recordsFor().filter(r=>r.km>0||r.from_pc||r.to_pc);$('app').innerHTML='<div class="page-top"><h1>Kilometers</h1>'+btn('+ Registratie','new-entry','primary')+'</div>'+recordFilters()+'<div class="team-kpis"><div>Ritten<strong>'+rows.length+'</strong></div><div>Kilometers<strong>'+fmt(kmOf(rows))+' km</strong></div></div><div class="card table-scroll"><table class="data-table team-table"><thead><tr><th>Datum</th><th>Medewerker</th><th>Project</th><th>Van</th><th>Naar</th><th>Rit</th><th>Km</th><th></th></tr></thead><tbody>'+(rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>'<tr><td>'+e(r.date)+'</td><td>'+e(memberName(r))+'</td><td>'+e(r.project)+'</td><td>'+e(r.from_pc)+'</td><td>'+e(r.to_pc)+'</td><td>'+(r.return_trip?'Retour':'Enkel')+'</td><td>'+fmt(r.km)+'</td><td><button class="btn small" data-team="edit-entry" data-id="'+e(r.id)+'">Wijzig</button></td></tr>').join('')||'<tr><td colspan="8">Geen ritten in deze periode</td></tr>')+'</tbody></table></div>';}

function projects(){const rows=state.data.projects;$('app').innerHTML=`<div class="page-top"><h1>Projecten</h1>${manager()?btn('+ Project','new-project','primary'):''}</div><div class="team-toolbar"><label><input id="showInactive" type="checkbox" ${state.showInactive?'checked':''}> Toon afgesloten projecten</label></div><div class="card table-scroll"><table class="data-table team-table"><thead><tr><th>Project</th><th>Omschrijving</th>${manager()&&feature('clients')?'<th>Klant</th>':''}${manager()&&feature('budgets')?'<th>Budget (alle jaren)</th>':''}<th>Totaal</th>${Array.from({length:12},(_,i)=>`<th>${i+1}</th>`).join('')}${manager()?'<th></th>':''}</tr></thead><tbody>${rows.filter(p=>p.active||state.showInactive).map(p=>{const rs=state.data.entries.filter(r=>r.project===p.code);return `<tr><td>${e(p.code)}</td><td>${e(p.name)}${!p.active?' · afgesloten':''}</td>${manager()&&feature('clients')?`<td>${e(clientName(p.client_id)||'—')}</td>`:''}${manager()&&feature('budgets')?`<td>${budgetDisplay(p)||'—'}</td>`:''}<td>${fmt(rs.reduce((n,r)=>n+r.minutes,0)/60)}</td>${Array.from({length:12},(_,i)=>`<td>${fmt(rs.filter(r=>Number(r.date.slice(5,7))===i+1).reduce((n,r)=>n+r.minutes,0)/60)}</td>`).join('')}${manager()?`<td><button class="btn small" data-team="edit-project" data-id="${e(p.code)}">Wijzig</button></td>`:''}</tr>`;}).join('')||'<tr><td colspan="16">Geen projecten</td></tr>'}</tbody></table></div>`;}
function dashRows(){return visible().filter(r=>matchMonth(r,state.dashMonth));}
function metric(label,value,sub,tone=''){return '<article class="dash-metric '+tone+'"><small>'+e(label)+'</small><strong>'+e(value)+'</strong><span>'+e(sub)+'</span></article>';}
function projectStats(p,rows){const rs=rows.filter(r=>r.project===p.code),total=minutesOf(rs),open=openOf(rs);return {rs,total,open,allocated:Math.max(0,total-open)};}
function progress(total,open){const n=total?Math.min(100,Math.max(0,(total-open)/total*100)):0;return '<div class="dash-progress" role="progressbar" aria-label="Toegewezen declaratie-uren" aria-valuenow="'+Math.round(n)+'" aria-valuemin="0" aria-valuemax="100"><i style="width:'+n+'%"></i></div>';}
function dashboardProject(p,rows){const x=projectStats(p,rows);return '<button type="button" class="dash-project" data-team="project-detail" data-id="'+e(p.code)+'"><div class="dash-project-title"><span class="dash-code">'+e(p.code)+'</span><span class="dash-project-status">'+(p.active?'Actueel':'Afgesloten')+'</span></div><strong>'+e(p.name)+'</strong><div class="dash-project-stats"><span><small>Uren</small><b>'+fmt(x.total/60)+'</b></span><span><small>Open uren</small><b>'+fmt(x.open/60)+'</b></span><span><small>Km</small><b>'+fmt(kmOf(x.rs))+'</b></span></div>'+progress(x.total,x.open)+budgetDisplay(p)+'<div class="dash-project-bottom"><span>'+fmt(x.allocated/60)+' u toegewezen</span><span aria-hidden="true">→</span></div></button>';}
function activityList(rows,limit=6){return rows.slice().sort((a,b)=>b.date.localeCompare(a.date)||String(b.start||'').localeCompare(String(a.start||''))).slice(0,limit).map(r=>'<button type="button" class="dash-activity" data-team="edit-entry" data-id="'+e(r.id)+'"><span class="dash-activity-mark">'+e(r.project.slice(0,2))+'</span><span class="dash-activity-text"><strong>'+e(projectName(r.project))+'</strong><small>'+e(r.activity)+' · '+e(r.date.slice(8,10)+' '+monthName(Number(r.date.slice(5,7)),true))+(state.member==='all'?' · '+e(memberName(r)):'')+'</small></span><b>'+fmt(r.minutes/60)+' u</b></button>').join('')||'<p class="dash-empty">Nog geen registraties in deze periode.</p>';}
function yearChart(rows){const months=Array.from({length:12},(_,i)=>{const r=rows.filter(x=>matchMonth(x,i+1));return {direct:minutesOf(r.filter(x=>x.kind==='DIRECT')),indirect:minutesOf(r.filter(x=>x.kind!=='DIRECT'))};});const max=Math.max(60,...months.map(x=>x.direct+x.indirect));return '<div class="dash-chart" aria-label="Uren per maand in '+state.year+'">'+months.map((m,i)=>'<button type="button" data-team="dash-period" data-month="'+(i+1)+'" class="dash-chart-month '+(state.dashMonth===i+1?'active':'')+'" title="'+e(monthName(i+1)+' · '+fmt((m.direct+m.indirect)/60)+' uur')+'" aria-label="'+e(monthName(i+1)+' · '+fmt((m.direct+m.indirect)/60)+' uur')+'"><span class="dash-bar-wrap"><span class="dash-bar" style="height:'+((m.direct+m.indirect)/max*100)+'%">'+(m.indirect?'<i class="indirect" style="height:'+(m.indirect/(m.direct+m.indirect)*100)+'%"></i>':'')+(m.direct?'<i style="height:'+(m.direct/(m.direct+m.indirect)*100)+'%"></i>':'')+'</span></span><small>'+e(monthName(i+1,true).slice(0,3))+'</small></button>').join('')+'</div><div class="dash-legend"><span><i></i> Direct</span><span><i></i> Indirect</span></div>';}
function overview(){
 const rows=dashRows(),total=minutesOf(rows),open=openOf(rows),direct=minutesOf(rows.filter(r=>r.kind==='DIRECT')),yearRows=visible(),period=state.dashMonth?monthName(state.dashMonth)+' '+state.year:String(state.year),scope=state.member==='all'?'Bedrijf':(state.data.members.find(x=>x.id===state.member)?.name||state.me.name);
 const projects=state.data.projects.filter(p=>p.active||rows.some(r=>r.project===p.code)).sort((a,b)=>projectStats(b,rows).total-projectStats(a,rows).total||a.code.localeCompare(b.code));
 const wholeCompany=manager()&&(state.me.mode==='solo'||state.member==='all'),claims=wholeCompany?state.data.claims.filter(r=>matchMonth(r,state.dashMonth)):[],sent=claims.filter(x=>x.status==='sent').reduce((s,r)=>s+r.amount,0);
 const finance=wholeCompany?metric('Verzonden declaraties',euro(sent),'Excl. btw · niet betaalstatus'):metric('Directe uren',fmt(direct/60)+' u',total?Math.round(direct/total*100)+'% van uren':'Geen uren');
 const filters='<div class="team-filterbar dash-filter">'+memberPicker()+select('Periode','dashMonth',monthOptions(),state.dashMonth)+'</div>';
 const projectCards=projects.map(p=>dashboardProject(p,rows)).join('')||'<p class="dash-empty">Nog geen projecten. '+(manager()?'Maak een project aan om te beginnen.':'Vraag je beheerder om een project.')+'</p>';
 $('app').innerHTML='<div class="page-top dash-title"><div><h1>Overzicht</h1><p>'+e(scope)+' · '+e(period)+'</p></div><div class="actions">'+btn('+ Registratie','new-entry','primary')+(manager()?btn('+ Project','new-project'):'')+'</div></div>'+filters+budgetAlerts()+'<div class="dash-metrics">'+metric('Gewerkte uren',fmt(total/60)+' u',fmt(direct/60)+' direct')+metric('Kilometers',fmt(kmOf(rows))+' km',rows.filter(r=>r.km>0).length+' ritregistraties')+metric('Open uren',fmt(open/60)+' u','Nog niet toegewezen aan declaratie','dash-open')+finance+'</div><div class="dash-overview-grid"><section class="card dash-panel"><header class="dash-panel-head"><h2>Uren per maand</h2><span>'+state.year+' · '+fmt(minutesOf(yearRows)/60)+' u</span></header>'+yearChart(yearRows)+'</section><section class="card dash-panel dash-recent"><header class="dash-panel-head"><h2>Recente registraties</h2><button type="button" class="team-link" data-team="dash-records">Alle</button></header>'+activityList(rows)+'</section></div><section class="dash-project-section"><header class="dash-panel-head"><h2>Projecten <span class="dash-count">'+projects.length+'</span></h2><button type="button" class="team-link" data-team="page" data-page="projecten">Projectoverzicht →</button></header><div class="dash-project-grid">'+projectCards+'</div></section><section class="card dash-extra"><button type="button" class="dash-extra-toggle" data-team="dash-more" aria-expanded="'+state.dashMore+'"><span>Uitgebreid overzicht</span><span>'+(state.dashMore?'−':'+')+'</span></button>'+(state.dashMore?'<div class="dash-extra-body"><div class="dash-breakdown"><div><small>Direct</small><strong>'+fmt(direct/60)+' u</strong></div><div><small>Indirect</small><strong>'+fmt((total-direct)/60)+' u</strong></div><div><small>Toegewezen aan declaraties (incl. concept)</small><strong>'+fmt((total-open)/60)+' u</strong></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Maand</th><th>Uren</th><th>Km</th><th>Open uren</th></tr></thead><tbody>'+Array.from({length:12},(_,i)=>{const r=yearRows.filter(x=>matchMonth(x,i+1));return '<tr><td>'+e(monthName(i+1))+'</td><td>'+fmt(minutesOf(r)/60)+'</td><td>'+fmt(kmOf(r))+'</td><td>'+fmt(openOf(r)/60)+'</td></tr>';}).join('')+'</tbody></table></div>'+(manager()?'<div class="actions">'+btn('Excel downloaden','export')+'</div>':'')+'</div>':'')+'</section>';
}
function projectDetail(code){const p=state.data.projects.find(p=>p.code===code);if(!p)return;const x=projectStats(p,dashRows()),period=state.dashMonth?monthName(state.dashMonth)+' '+state.year:String(state.year);const d=$('modal');d.className='team-dialog';d.innerHTML='<header class="team-dialog-head"><div><small class="team-muted">'+e(p.code+' · '+period)+'</small><h2>'+e(p.name)+'</h2></div><button class="team-close" type="button" data-team="close" aria-label="Sluiten">×</button></header><div class="team-dialog-body"><div class="dash-metrics dash-detail-metrics">'+metric('Uren',fmt(x.total/60)+' u','Geregistreerd')+metric('Open uren',fmt(x.open/60)+' u','Nog niet toegewezen')+metric('Kilometers',fmt(kmOf(x.rs))+' km','')+'</div>'+progress(x.total,x.open)+budgetDisplay(p)+'<h3 class="dash-detail-heading">Recente registraties</h3>'+activityList(x.rs,8)+'<h3 class="dash-detail-heading">Activiteiten</h3>'+[...new Set(x.rs.map(r=>r.activity))].map(a=>'<div class="dash-detail-line"><span>'+e(a)+'</span><b>'+fmt(minutesOf(x.rs.filter(r=>r.activity===a))/60)+' u</b></div>').join('')+'</div><div class="actions team-dialog-footer"><button type="button" class="btn" data-team="project-records" data-id="'+e(code)+'">Alle registraties</button>'+(manager()?'<button type="button" class="btn" data-team="edit-project" data-id="'+e(code)+'">Project wijzigen</button>':'')+(p.active?'<button type="button" class="btn primary" data-team="project-register" data-id="'+e(code)+'">+ Registratie</button>':'')+'</div>';if(!d.open)d.showModal();}
function dialog(title,html,action){const d=$('modal');d.className='team-dialog';d.innerHTML=`<header class="team-dialog-head"><h2>${title}</h2><button type="button" class="team-close" data-team="close" aria-label="Sluiten">×</button></header><form id="editForm" data-submit="${action}"><div class="team-dialog-body">${html}<div class="team-error" role="alert"></div></div><div class="actions team-dialog-footer">${btn('Annuleren','close')}<button class="btn primary" type="submit">Bewaren</button></div></form>`;if(!d.open)d.showModal();}
function editEntry(r=null,defaults={}){if(!state.data.projects.length){notice('Voeg eerst een project toe.',true);return;}state.edit=r;state.routeQuote=null;const date=r?.date||defaults.date||state.anchor;const start=r?.start||defaults.start||'',end=r?.end||defaults.end||'',duration=LAAgenda.duration(start,end);const ps=state.data.projects.filter(p=>p.active||p.code===r?.project);if(!ps.length){notice('Geen actieve projecten.',true);return;}let target=defaults.member|| (manager()&&state.member!=='all'?state.member:state.me.id);state.timerDraft=!!defaults.timer;dialog(r?'Registratie wijzigen':'Registratie toevoegen',`<div class="team-row team-entry-grid">${field('Datum','edDate','date',date,'required')}${manager()&&!r?select('Medewerker','edMember',state.data.members.filter(x=>x.active).map(m=>[m.id,m.name]),target):''}${select('Project','edProject',ps.map(p=>[p.code,p.code+' · '+p.name]),r?.project||defaults.project||state.project)}${select('Activiteit','edActivity',state.data.activities.map(a=>[a.name,a.name]),r?.activity||defaults.activity)}</div><div class="team-time-grid">${field('Begintijd','edStart','time',start)}${field('Eindtijd','edEnd','time',end)}${field('Uren','edHours','number',duration??(r?r.minutes/60:defaults.hours??1),'min="0.016" max="24" step="any" required '+(duration!==null?'readonly':''))}</div><div class="field"><label for="edNote">Omschrijving (optioneel)</label><textarea id="edNote" maxlength="2000" placeholder="">${e(r?.note||defaults.note||'')}</textarea></div><details class="team-mileage" ${r?.km||r?.from_pc||r?.to_pc?'open':''}><summary><span>Kilometerregistratie</span><span class="team-muted" id="routeSummary">${fmt(r?.km||0)} km</span></summary><div class="team-mileage-body"><div class="team-row">${field('Van postcode','edFrom','text',r?.from_pc||'','placeholder="1234 AB" maxlength="8"')}${field('Naar postcode','edTo','text',r?.to_pc||'','placeholder="5678 CD" maxlength="8"')}</div><div class="team-route-actions"><label class="team-check"><input type="checkbox" id="edReturn" ${r?.return_trip===0?'':'checked'}> Retourrit</label>${btn('Bereken afstand','route','small')}</div><div class="team-route-result">${field('Kilometers','edKm','number',r?.km||0,'min="0" step="any"')}<span id="routeResult" role="status" class="team-muted"></span></div><p class="team-note">Indicatieve autoroute vanaf postcodecentra. Kaartgegevens: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">Kaart verbeteren</a> . Je kunt kilometers ook zelf invullen.</p></div></details>${r?'<div class="team-actions" style="margin-top:14px">'+repeatButton(r)+btn('Verwijderen','delete-entry','small danger')+'</div>':''}`,'entry');}
function editProject(p){state.editProject=p;const clientOpts=[['','Geen klant'],...(state.data.clients||[]).filter(c=>c.active||c.id===p?.client_id).map(c=>[c.id,c.name])];dialog(p?'Project wijzigen':'Project toevoegen',field('Projectnummer','prCode','text',p?.code||'',p?'readonly required':'required')+field('Omschrijving','prName','text',p?.name||'','required')+field('Uurtarief (EUR, 0 = standaard)','prRate','number',(p?.rate||0)/100,'min="0" step="0.01"')+(feature('clients')?select('Klant','prClient',clientOpts,p?.client_id||''):'')+(feature('budgets')?'<div class="team-row">'+field('Urenbudget (0 = geen)','prBudgetHours','number',(p?.budget_minutes||0)/60,'min="0" max="100000" step="any"')+field('Budget excl. btw (€; 0 = geen)','prBudgetMoney','number',(p?.budget_cents||0)/100,'min="0" max="10000000" step="0.01"')+'</div><p class="team-note">Budget geldt voor alle jaren; euroverbruik is een indicatie op basis van het huidige uurtarief.</p>':'')+'<label><input type="checkbox" id="prActive" '+(p?.active===0?'':'checked')+'> Actueel</label>','project');}
function clientName(id){return state.data.clients?.find(c=>c.id===id)?.name||'';}
function budgetItems(p){if(!manager()||!feature('budgets'))return [];const out=[];if(p.budget_minutes>0)out.push({label:'Urenbudget',used:p.used_minutes||0,cap:p.budget_minutes,show:v=>fmt(v/60)+' u',known:true});if(p.budget_cents>0)out.push({label:'Eurobudget (indicatief)',used:p.used_cents||0,cap:p.budget_cents,show:euro,known:p.estimate_available});return out;}
function budgetDisplay(p){const name=feature('clients')&&manager()?clientName(p.client_id):'';return (name?'<small class="module-client-label">'+e(name)+'</small>':'')+budgetItems(p).map(b=>{const ratio=b.known?b.used/b.cap:0;const warn=feature('warnings')&&b.known&&ratio>=.8;return '<div class="module-budget '+(warn?(ratio>=1?'over':'near'):'')+'"><div><span>'+e(b.label)+'</span><b>'+e(b.known?b.show(b.used)+' / '+b.show(b.cap):b.show(b.cap)+' · tarief ontbreekt')+'</b></div>'+(b.known?'<div class="module-budget-track"><i style="width:'+Math.min(100,Math.max(0,ratio*100))+'%"></i></div>':'')+(warn?'<small>'+(ratio>=1?(ratio>1?'Budget overschreden':'Budget bereikt'):'Budget bijna bereikt')+'</small>':'')+'</div>';}).join('');}
function budgetAlerts(){if(!manager()||!feature('warnings')||!feature('budgets'))return '';const projects=state.data.projects.filter(p=>p.active&&budgetItems(p).some(b=>b.known&&b.used/b.cap>=.8));return projects.length?'<section class="module-alert"><strong>Budgetwaarschuwingen · '+projects.length+'</strong><div>'+projects.map(p=>'<button type="button" data-team="project-detail" data-id="'+e(p.code)+'">'+e(p.code+' · '+p.name)+'</button>').join('')+'</div></section>':'';}
function clientsPage(){if(!manager()||!feature('clients')){state.page='overzicht';render();return;}const rows=state.data.clients||[];$('app').innerHTML='<div class="page-top"><h1>Klanten</h1>'+btn('+ Klant','new-client','primary')+'</div><div class="card table-scroll"><table class="data-table team-table"><thead><tr><th>Naam</th><th>Contactpersoon</th><th>E-mail</th><th>Telefoon</th><th>Projecten</th><th>Status</th><th></th></tr></thead><tbody>'+(rows.map(c=>'<tr><td>'+e(c.name)+'</td><td>'+e(c.contact)+'</td><td>'+e(c.email)+'</td><td>'+e(c.phone)+'</td><td>'+state.data.projects.filter(p=>p.client_id===c.id).length+'</td><td>'+(c.active?'Actief':'Inactief')+'</td><td><button class="btn small" data-team="edit-client" data-id="'+e(c.id)+'">Wijzig</button></td></tr>').join('')||'<tr><td colspan="7">Geen klanten</td></tr>')+'</tbody></table></div>';}
function editClient(c){if(!manager()||!feature('clients'))return;state.editClient=c;dialog(c?'Klant wijzigen':'Klant toevoegen',field('Naam / bedrijf','clName','text',c?.name||'','required maxlength="200"')+field('Contactpersoon','clContact','text',c?.contact||'')+field('E-mailadres','clEmail','email',c?.email||'')+field('Telefoon','clPhone','tel',c?.phone||'')+'<label><input type="checkbox" id="clActive" '+(c?.active===0?'':'checked')+'> Actief</label>','client');}
function repeatButton(r){return pref('repeat_entry')?'<button type="button" class="btn small" data-team="repeat-entry" data-id="'+e(r.id)+'">Herhalen</button>':'';}
function repeatEntry(r){if(!pref('repeat_entry')||!r||!state.data.projects.some(p=>p.code===r.project&&p.active)){notice('Herhalen is niet beschikbaar voor dit project.',true);return;}editEntry(null,{date:today(),project:r.project,activity:r.activity,hours:r.minutes/60,note:r.note,member:state.me.id});}
function timerKey(){return 'la-team-stopwatch-'+state.me.id;}
function timerRead(){try{const t=JSON.parse(localStorage.getItem(timerKey())||'null');return t&&Number.isFinite(t.elapsed)&&t.elapsed>=0&&Number.isFinite(t.started)&&t.started>=0&&typeof t.date==='string'?t:null;}catch{return null;}}
function timerWrite(t){if(t)localStorage.setItem(timerKey(),JSON.stringify(t));else localStorage.removeItem(timerKey());}
function elapsed(t){return t?Math.max(0,t.elapsed+(t.started?Math.max(0,Date.now()-t.started):0)):0;}
function timerText(ms){const seconds=Math.floor(ms/1000);return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(v=>String(v).padStart(2,'0')).join(':');}
function stopwatchPanel(){if(!pref('stopwatch'))return '';const t=timerRead();return '<section class="card module-timer"><div><small>Stopwatch</small><strong id="timerDisplay">'+timerText(elapsed(t))+'</strong></div><div class="actions">'+(!t?btn('Start','timer-start','primary'):(t.started?btn('Pauze','timer-pause'):btn('Doorgaan','timer-resume'))+btn('Registreren','timer-register','primary')+btn('Wissen','timer-clear'))+'</div></section>';}
function timerAction(a){if(!pref('stopwatch'))return;let t=timerRead();if(a==='timer-start'&&!t){t={date:today(),elapsed:0,started:Date.now()};timerWrite(t);}else if(a==='timer-pause'&&t?.started){timerWrite({...t,elapsed:elapsed(t),started:0});}else if(a==='timer-resume'&&t&&!t.started){timerWrite({...t,started:Date.now()});}else if(a==='timer-clear'&&t){if(confirm('Stopwatch wissen? Niet opgeslagen tijd gaat verloren.'))timerWrite(null);}else if(a==='timer-register'&&t){const ms=elapsed(t);if(ms<1000){notice('Laat de stopwatch eerst lopen.',true);return;}timerWrite({...t,elapsed:ms,started:0});render();editEntry(null,{date:t.date,hours:Math.min(1440,Math.max(1,Math.round(ms/60000)))/60,member:state.me.id,timer:true});if(ms>86400000)notice('Meer dan 24 uur gemeten. Verdeel de tijd over meerdere registraties; resterende tijd blijft in de stopwatch.',true);return;}render();}
setInterval(()=>{if(state.me&&pref('stopwatch')&&$('timerDisplay'))$('timerDisplay').textContent=timerText(elapsed(timerRead()));},1000);
function claims(){const ps=state.data.projects;if(!state.claimProject)state.claimProject=ps[0]?.code||'';const rows=state.data.entries.filter(r=>r.project===state.claimProject&&r.minutes>r.billed);$('app').innerHTML=`<div class="page-top"><h1>Declaraties</h1></div><section class="card team-card"><h2>Nieuwe declaratie</h2><form id="claimForm">${select('Project','claimProject',ps.map(p=>[p.code,p.code+' · '+p.name]),state.claimProject)}<div class="table-scroll"><table class="data-table team-table"><thead><tr><th>Datum</th><th>Medewerker</th><th>Activiteit</th><th>Open (uur)</th><th>Declareren (uur)</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.date)}</td><td>${e(memberName(r))}</td><td>${e(r.activity)}</td><td>${fmt((r.minutes-r.billed)/60)}</td><td><input type="number" min="0" max="${(r.minutes-r.billed)/60}" step="any" value="${(r.minutes-r.billed)/60}" data-allocate="${e(r.id)}"></td></tr>`).join('')||'<tr><td colspan="5">Geen openstaande uren</td></tr>'}</tbody></table></div><div class="team-row">${select('Methode','claimMethod',[['hours','Uren'],['fixed','Vast bedrag'],['percentage','Percentage']],'hours')}${field('Datum','claimDate','date',state.anchor,'required')}${field('Grondslag / contractbedrag (€)','claimBase','number',0,'min="0" step="0.01"')}${field('Percentage','claimPct','number',0,'min="0" max="100" step="any"')}${field('Bedrag excl. btw (€)','claimAmount','number',0,'min="0" step="0.01" required')}${field('Kenmerk','claimRef')}</div><button class="btn primary" type="submit">Concept vastleggen</button></form></section><div class="card table-scroll"><table class="data-table team-table"><thead><tr><th>Datum</th><th>Project</th><th>Bedrag</th><th>Status</th><th></th></tr></thead><tbody>${state.data.claims.map(c=>`<tr><td>${e(c.date)}</td><td>${e(c.project)}</td><td>${euro(c.amount)}</td><td>${e(({draft:'Concept',sent:'Verzonden',void:'Vervallen'})[c.status])}</td><td>${c.status==='draft'?`<button class="btn small" data-team="claim-status" data-id="${e(c.id)}" data-status="sent">Verzonden</button> <button class="btn small" data-team="claim-status" data-id="${e(c.id)}" data-status="void">Vervallen</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;suggestAmount();}
function allocations(){return Array.from(document.querySelectorAll('[data-allocate]')).map(el=>({id:el.dataset.allocate,minutes:Math.round(Number(el.value)*60)})).filter(x=>x.minutes>0);}
function suggestAmount(){if(!$('claimAmount'))return;const p=state.data.projects.find(p=>p.code===state.claimProject),method=val('claimMethod'),hours=allocations().reduce((a,r)=>a+r.minutes,0)/60;const amount=method==='hours'?hours*(p?.rate||state.me.rate||0)/100:method==='percentage'?num('claimBase')*num('claimPct')/100:num('claimBase');$('claimAmount').value=amount.toFixed(2);}
function members(){$('app').innerHTML=`<div class="page-top"><h1>Medewerkers</h1>${btn('+ Uitnodigen','invite','primary')}</div><div class="card table-scroll"><table class="data-table"><thead><tr><th>Naam</th><th>E-mail</th><th>Rol</th><th>Status</th><th></th></tr></thead><tbody>${state.data.members.map(m=>`<tr><td>${e(m.name)}</td><td>${e(m.email)}</td><td>${e(({owner:'Eigenaar',admin:'Administratie',member:'Medewerker'})[m.role])}</td><td>${m.active?'Actief':'Inactief'}</td><td>${m.active&&m.role!=='owner'?`<button class="btn small" data-team="disable-member" data-id="${e(m.id)}">Deactiveren</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function moduleSwitch(id,title,description,active){return '<label class="module-switch"><span><strong>'+e(title)+'</strong><small>'+e(description)+'</small></span><input type="checkbox" id="'+id+'" '+(active?'checked':'')+'><span class="module-toggle" aria-hidden="true"></span></label>';}
function optionalSettings(){return '<section class="card team-card module-settings"><h2>Extra functies</h2>'+(owner()?'<form id="moduleForm">'+moduleSwitch('modClients','Klantenbeheer','Klanten toevoegen en koppelen aan projecten.',feature('clients'))+moduleSwitch('modBudgets','Projectbudgetten','Budget in uren en/of euro’s per project.',feature('budgets'))+moduleSwitch('modWarnings','Budgetwaarschuwingen','Signaleren vanaf 80% van het budget.',feature('warnings'))+'<div class="actions"><button class="btn primary" type="submit">Bedrijfsopties bewaren</button></div></form>':'')+'<h3>Persoonlijk</h3><form id="preferenceForm">'+moduleSwitch('prefStopwatch','Stopwatch','Tijd meten in de agenda; lopende timer blijft op dit apparaat.',pref('stopwatch'))+moduleSwitch('prefRepeat','Registratie herhalen','Kopieer project, activiteit, omschrijving en uren naar vandaag.',pref('repeat_entry'))+moduleSwitch('prefDark','Donkere modus','Donkere weergave van je werkruimte.',pref('dark'))+'<div class="actions"><button class="btn primary" type="submit">Persoonlijke opties bewaren</button></div></form></section>';}
function settings(){$('app').innerHTML=`<div class="page-top"><h1>Instellingen</h1></div>${optionalSettings()}${owner()?`<section class="card team-card"><h2>Bedrijf</h2><form id="companyForm">${field('Naam','companyName','text',state.me.company,'required')}${field('Standaard uurtarief (EUR)','companyRate','number',state.me.rate/100,'min="0" step="0.01"')}<div class="field"><label>Logo</label><input id="companyLogo" type="file" accept="image/png,image/jpeg,image/webp"></div><label><input id="removeLogo" type="checkbox"> Logo verwijderen</label><div class="actions"><button class="btn primary" type="submit">Bewaren</button></div></form></section><section class="card team-card"><h2>Activiteiten</h2><form id="activityForm">${select('Bestaande activiteit','activityPick',[['','Nieuwe activiteit'],...state.data.activities.map(a=>[a.name,a.name])],'')}${field('Naam','activityName','text','','required')}${select('Type','activityKind',[['DIRECT','Direct'],['INDIRECT','Indirect']],'DIRECT')}<button class="btn primary" type="submit">Bewaren</button></form></section><section class="card team-card"><h2>STACK-back-up</h2><p class="team-note">De database is leidend. Een back-up krijgt een nieuwe bestandsnaam en overschrijft geen bestaande Excel-bestanden.</p><form id="storageForm">${field('WebDAV-map','storageUrl','url','','required placeholder="https://account.stack.storage/remote.php/webdav/uren"')}${field('STACK-gebruiker','storageUser','text','','required')}${field('WebDAV-token','storageToken','password','','required')}<button class="btn primary" type="submit">Koppeling testen en bewaren</button></form><div class="actions" style="margin-top:15px">${btn('Excel downloaden','export')}${btn('Back-up naar STACK','backup','primary')}</div></section>`:''}`;}
async function xlsxBytes(){if(!window.XLSX)throw Error('Excelbibliotheek niet geladen');const data=await api('/export');const book=XLSX.utils.book_new();for(const [key,value] of Object.entries(data)){let list=Array.isArray(value)?value:[value];XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(list),key.slice(0,31));}return XLSX.write(book,{bookType:'xlsx',type:'array'});}
async function logoUpload(){if(checked('removeLogo'))return '';const f=$('companyLogo').files[0];if(!f)return state.me.logo||'';if(f.size>6e6||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Kies een PNG, JPG of WebP van maximaal 6 MB');const bm=await createImageBitmap(f);const c=document.createElement('canvas');let scale=Math.min(1,300/bm.width,120/bm.height);for(let i=0;i<7;i++){c.width=Math.max(1,Math.round(bm.width*scale));c.height=Math.max(1,Math.round(bm.height*scale));c.getContext('2d').drawImage(bm,0,0,c.width,c.height);const url=c.toDataURL('image/webp',.8);if(url.length<24000){bm.close();return url;}scale*=.7;}bm.close();throw Error('Logo te groot');}
async function submit(form){switch(form.id){case 'loginForm':{state.token='';sessionStorage.removeItem('la-team-token');state.base=endpoint(val('base'));const b={slug:val('slug'),email:val('email'),password:val('password'),company:val('company'),name:val('name'),key:val('setupKey'),mode:val('mode'),invite:val('invite')};const r=await api('/'+state.login,'POST',b);state.token=r.token;sessionStorage.setItem('la-team-token',r.token);localStorage.setItem('la-team-api',state.base);state.page='overzicht';try{await load();}catch(err){reset();throw err;}break;}case 'editForm':{switch(form.dataset.submit){case 'entry':{const r=state.edit;await api('/entries','POST',{id:r?.id||crypto.randomUUID(),rev:r?.rev,member_id:r?.member_id||val('edMember')||state.me.id,project:val('edProject'),date:val('edDate'),activity:val('edActivity'),note:val('edNote'),start:val('edStart'),end:val('edEnd'),minutes:minutes('edHours'),km:num('edKm'),from_pc:val('edFrom'),to_pc:val('edTo'),return_trip:checked('edReturn')});if(state.timerDraft){const t=timerRead();const d=LAAgenda.duration(val('edStart'),val('edEnd'));const savedMs=(d===null?minutes('edHours'):Math.round(d*60))*60000;if(t&&t.elapsed-savedMs>=60000){timerWrite({...t,elapsed:t.elapsed-savedMs,started:0});}else timerWrite(null);state.timerDraft=false;}state.anchor=val('edDate');state.year=Number(state.anchor.slice(0,4));break;}case 'project':await api('/projects','POST',{code:val('prCode'),name:val('prName'),rate:cents('prRate'),active:checked('prActive'),...(feature('clients')?{client_id:val('prClient')}:{}),...(feature('budgets')?{budget_minutes:minutes('prBudgetHours'),budget_cents:cents('prBudgetMoney')}:{})});break;case 'client':await api('/clients','POST',{id:state.editClient?.id,name:val('clName'),contact:val('clContact'),email:val('clEmail'),phone:val('clPhone'),active:checked('clActive')});break;case 'invite':{const r=await api('/invites','POST',{email:val('inviteEmail'),role:val('inviteRole')});$('modal').close();await load();$('modal').innerHTML=`<h2>Uitnodiging</h2><p>Deel deze eenmalige code rechtstreeks met de medewerker. Geldig gedurende 48 uur.</p><p class="team-code">${e(r.invite)}</p><div class="actions">${btn('Sluiten','close','primary')}</div>`;$('modal').showModal();return;}}$('modal').close();await load();notice('Opgeslagen');break;}case 'claimForm':await api('/claims','POST',{project:state.claimProject,date:val('claimDate'),method:val('claimMethod'),amount:cents('claimAmount'),reference:val('claimRef'),allocations:allocations(),base:cents('claimBase'),percentage:num('claimPct')});await load();notice('Declaratie vastgelegd');break;case 'moduleForm':await api('/modules','POST',{clients:checked('modClients'),budgets:checked('modBudgets'),warnings:checked('modBudgets')&&checked('modWarnings')});await load();notice('Bedrijfsopties opgeslagen');break;case 'preferenceForm':await api('/preferences','POST',{stopwatch:checked('prefStopwatch'),repeat_entry:checked('prefRepeat'),dark:checked('prefDark')});await load();notice('Persoonlijke opties opgeslagen');break;case 'companyForm':await api('/company','POST',{name:val('companyName'),rate:cents('companyRate'),logo:await logoUpload()});await load();notice('Opgeslagen');break;case 'activityForm':await api('/activities','POST',{name:val('activityName'),kind:val('activityKind')});await load();notice('Activiteit opgeslagen');break;case 'storageForm':await api('/storage','POST',{url:val('storageUrl'),user:val('storageUser'),token:val('storageToken')});form.reset();notice('STACK-koppeling opgeslagen');break;}}
async function route(){
 const from=val('edFrom'),to=val('edTo'),dialog=$('modal'),input=$('edKm'),result=$('routeResult'),button=dialog.querySelector('[data-team="route"]'),err=dialog.querySelector('.team-error');
 if(!from||!to)throw Error('Vul beide postcodes in');
 if(err)err.textContent='';
 if(result)result.textContent='Afstand berekenen…';
 if(button)button.disabled=true;
 try{
  const r=await api('/route','POST',{from,to});
  if(!dialog.open||$('edKm')!==input||val('edFrom')!==from||val('edTo')!==to)return;
  if(!Number.isFinite(r.km)||r.km<0)throw Error('Geen geldige afstand ontvangen.');
  const km=r.km*(checked('edReturn')?2:1);input.value=km.toFixed(2);
  state.routeQuote={from,to,km:r.km};if($('routeSummary'))$('routeSummary').textContent=fmt(km)+' km';
  if(result)result.textContent=(checked('edReturn')?'Retourrit':'Enkele reis')+' · indicatief';
 }catch(error){if(result)result.textContent='';throw error;}
 finally{if(button)button.disabled=false;}
}
async function action(a,el){const id=el.dataset.id;switch(a){case 'login-mode':state.login='login';render();return;case 'join-mode':state.login='join';render();return;case 'setup-mode':state.login='setup';render();return;case 'close':$('modal').close();return;}if(!state.me)return;switch(a){case 'page':state.page=el.dataset.page;if(state.page==='registraties'||state.page==='kilometers'){state.recordProject='';state.recordMonth=0;}render();break;case 'nav-more':state.navMore=!state.navMore;render();break;case 'dash-period':state.dashMonth=state.dashMonth===Number(el.dataset.month)?0:Number(el.dataset.month);render();break;case 'dash-more':state.dashMore=!state.dashMore;render();break;case 'project-detail':projectDetail(id);break;case 'dash-records':state.page='registraties';state.recordProject='';state.recordMonth=state.dashMonth;render();break;case 'project-records':$('modal').close();state.page='registraties';state.recordProject=id;state.recordMonth=state.dashMonth;render();break;case 'project-register':editEntry(null,{project:id,date:state.year===Number(today().slice(0,4))?today():state.year+'-01-01'});break;case 'new-entry':editEntry(null,{project:state.page==='registraties'||state.page==='kilometers'?state.recordProject:'',date:state.page==='overzicht'?(state.year===Number(today().slice(0,4))?today():state.year+'-01-01'):state.anchor});break;case 'edit-entry':editEntry(state.data.entries.find(r=>r.id===id));break;case 'delete-entry':if(confirm('Registratie verwijderen?')){await api('/entries/delete','POST',{id:state.edit.id,rev:state.edit.rev});$('modal').close();await load();notice('Verwijderd');}break;case 'new-client':editClient(null);break;case 'edit-client':editClient(state.data.clients.find(c=>c.id===id));break;case 'repeat-entry':repeatEntry(state.data.entries.find(r=>r.id===id));break;case 'timer-start':case 'timer-pause':case 'timer-resume':case 'timer-register':case 'timer-clear':timerAction(a);break;case 'new-project':editProject(null);break;case 'edit-project':editProject(state.data.projects.find(p=>p.code===id));break;case 'invite':dialog('Medewerker uitnodigen',field('E-mailadres','inviteEmail','email','','required')+select('Rol','inviteRole',[['member','Medewerker'],['admin','Administratie']],'member'),'invite');break;case 'disable-member':if(confirm('Account deactiveren? Uren blijven bewaard.')){await api('/members/disable','POST',{id});await load();}break;case 'claim-status':if(confirm('Status aanpassen?')){await api('/claims/status','POST',{id,status:el.dataset.status});await load();}break;case 'route':await route();break;case 'export':{const bytes=await xlsxBytes(),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));let a=document.createElement('a');a.href=url;a.download='Uren-'+state.me.slug+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);break;}case 'backup':{const b=await api('/backup','POST',await xlsxBytes());notice('Back-up opgeslagen: '+b.name);break;}}}
function agendaAction(el){if(!state.me||state.page!=='agenda')return;const a=el.dataset.action;switch(a){case 'agenda-new':{const start=el.dataset.time||'';const m=LAAgenda.minute(start);const end=m!==null&&m+60<1440?String(Math.floor((m+60)/60)).padStart(2,'0')+':'+String((m+60)%60).padStart(2,'0'):'';editEntry(null,{date:el.dataset.date||state.anchor,start:end?start:'',end});break;}case 'agenda-edit':state.selected=el.dataset.id;editEntry(state.data.entries.find(r=>r.id===state.selected));break;case 'agenda-today':navigate(today());break;case 'agenda-prev':case 'agenda-next':{const d=a==='agenda-prev'?-1:1;if(state.mode==='maand'){let day=new Date(state.anchor+'T12:00:00');day.setDate(1);day.setMonth(day.getMonth()+d);navigate(LAAgenda.iso(day));}else navigate(LAAgenda.shift(state.anchor,d*(state.mode==='dag'?1:7)));break;}case 'agenda-mode':state.mode=el.dataset.mode;render();break;case 'agenda-select-day':state.mode='dag';navigate(el.dataset.date);break;}}
function navigate(d){state.anchor=d;if(Number(d.slice(0,4))!==state.year){state.year=Number(d.slice(0,4));void task(load);}else render();}
document.addEventListener('submit',ev=>{ev.preventDefault();void task(()=>submit(ev.target));});document.addEventListener('click',ev=>{const el=ev.target.closest('[data-team]');if(el){ev.preventDefault();void task(()=>action(el.dataset.team,el));return;}const ag=ev.target.closest('[data-action]');if(ag){ev.preventDefault();agendaAction(ag);}});document.addEventListener('change',ev=>{const id=ev.target.id;if(id==='modBudgets'&&!checked(id)&&$('modWarnings'))$('modWarnings').checked=false;if(id==='modWarnings'&&checked(id)&&$('modBudgets'))$('modBudgets').checked=true;if(id==='edReturn'&&state.routeQuote&&state.routeQuote.from===val('edFrom')&&state.routeQuote.to===val('edTo')){const km=state.routeQuote.km*(checked('edReturn')?2:1);$('edKm').value=km.toFixed(2);$('routeSummary').textContent=fmt(km)+' km';$('routeResult').textContent=(checked('edReturn')?'Retourrit':'Enkele reis')+' · indicatief';}if(id==='year'&&state.me){state.year=Number(val('year'));state.dashMonth=state.year===Number(today().slice(0,4))?Number(today().slice(5,7)):0;state.anchor=state.year===Number(today().slice(0,4))?today():state.year+'-01-01';void task(load);}if(id==='dashMonth'){state.dashMonth=Number(val(id));render();}if(id==='recordMonth'){state.recordMonth=Number(val(id));render();}if(id==='recordProject'){state.recordProject=val(id);render();}if(id==='memberFilter'){state.member=val(id);render();}if(id==='agendaProjectFilter'){state.project=val(id);render();}if(id==='agendaKindFilter'){state.kind=val(id);render();}if(id==='showInactive'){state.showInactive=checked(id);render();}if(id==='activityPick'){const a=state.data.activities.find(x=>x.name===val(id));$('activityName').value=a?.name||'';$('activityName').readOnly=!!a;$('activityKind').value=a?.kind||'DIRECT';}if(id==='claimProject'){state.claimProject=val(id);render();}});document.addEventListener('input',ev=>{if(['edFrom','edTo','edKm'].includes(ev.target.id)){state.routeQuote=null;if($('routeResult'))$('routeResult').textContent='';if($('routeSummary'))$('routeSummary').textContent=fmt(num('edKm'))+' km';}if(['edStart','edEnd'].includes(ev.target.id)){const d=LAAgenda.duration(val('edStart'),val('edEnd'));if(d!==null)$('edHours').value=d;$('edHours').readOnly=!!(val('edStart')&&val('edEnd'));}if(ev.target.dataset.allocate||['claimBase','claimPct','claimMethod'].includes(ev.target.id))suggestAmount();});$('status').addEventListener('click',()=>{if(state.me)void task(async()=>{try{await api('/logout','POST',{});}finally{reset();}});});LAAgendaDrag.install({element:document.body,onSelect:r=>{if(state.me&&state.page==='agenda')editEntry(null,r);}});render();if(state.base&&state.token)void task(async()=>{try{state.base=endpoint(state.base);await load();}catch(err){reset();throw err;}});
})();